class Solution:
    def reverseWords(self, s: list[str]) -> None:
        """Do not return anything, modify s in-place instead."""
        def reverse(l: int, r: int) -> None:
            while l < r:
                s[l], s[r] = s[r], s[l]
                l += 1
                r -= 1

        n = len(s)
        reverse(0, n - 1)                  # words now in the right order, but each one mirrored
        start = 0
        for i in range(n + 1):             # i == n acts as a sentinel that closes the last word
            if i == n or s[i] == " ":
                reverse(start, i - 1)      # every char is swapped at most twice overall
                start = i + 1

